public class MemoryDemo {

    public static void main(String[] args) {
        // 1. Print heap usage
        Runtime rt = Runtime.getRuntime();
        long usedMB = (rt.totalMemory() - rt.freeMemory()) / 1_048_576;
        long maxMB  = rt.maxMemory() / 1_048_576;
        System.out.printf("Heap used: %d MB / max: %d MB%n", usedMB, maxMB);

        // 2. WeakReference
        java.lang.ref.WeakReference<byte[]> ref = new java.lang.ref.WeakReference<>(new byte[1024 * 1024]);

        // 3. Hint GC and check
        System.gc();
        if (ref.get() == null) System.out.println("reclaimed");
        else System.out.println("still live");

        // 4. Allocation loop
        for (int i = 0; i < 10_000; i++) {
            byte[] data = new byte[100];
        }
        System.out.println("allocation complete");
    }
}

