import java.util.*;

public class LeakDemo {
    static Map<Integer, byte[]> leakyCache = new HashMap<>();

    static void cacheEntry(int key) {
        leakyCache.put(key, new byte[10_240]);
    }

    public static void main(String[] args) {
        for (int i = 0; i < 100; i++) cacheEntry(i);
        System.out.println("Leaky cache size: " + leakyCache.size()); // 100

        Runtime rt = Runtime.getRuntime();
        long usedMB = (rt.totalMemory() - rt.freeMemory()) / 1_048_576;
        System.out.println("Heap used: " + usedMB + " MB");

        // Fixed: bounded LRU cache
        Map<Integer, byte[]> lruCache = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, byte[]> eldest) {
                return size() > 10;
            }
        };
        for (int i = 0; i < 100; i++) lruCache.put(i, new byte[10_240]);
        System.out.println("LRU cache size: " + lruCache.size()); // 10
    }
}
